dateien.bruecke.py:
"""Online demo of Chat Team (GitHub Pages, no server): the ways of server.py, answered inside the browser (Pyodide).
The logic is the unchanged _gast/ of the tool (rezeption.py, gedaechtnis.py, gast.py, probe_ki.py, anschluss.py); this file only does
what server.py does around it. Data lie in the browser's memory and are kept by demo.js in localStorage of the visitor, nothing is sent.
Without CHAT_TEAM_KI every answer is the demo of probe_ki.py: no model, no key."""
import base64, importlib.util, json, os, sys
from urllib.parse import parse_qs

WZ = os.path.dirname(os.path.abspath(__file__))
DATEN = os.path.join(WZ, 'daten')
os.environ['REZEPTION_DATEN'] = DATEN
os.environ.pop('CHAT_TEAM_KI', None)
HAUS = json.load(open(os.path.join(WZ, 'haus.json'), encoding='utf-8'))

_MOD = {}
def _modul(name):
    if name not in _MOD:
        p = os.path.join(WZ, '_gast')
        if p not in sys.path:
            sys.path.insert(0, p)
        sp = importlib.util.spec_from_file_location(name, os.path.join(p, name + '.py'))
        m = importlib.util.module_from_spec(sp); sys.modules[name] = m; sp.loader.exec_module(m); _MOD[name] = m
    return _MOD[name]

_GAST = None
def gast():
    global _GAST
    if _GAST is None:
        g = _modul('gast')
        _modul('gedaechtnis'); R = _modul('rezeption')
        R.einbinden(g)
        _GAST = g
    return _GAST

def rez():
    gast()
    return _modul('rezeption')


def _gast_post(d, probe):
    """What handler.do_POST of gast.py does for the chat window (POST /api/gast)."""
    g, R = gast(), rez()
    R.LOKAL.probe = bool(probe)          # «Try the chat» (probe.html?probe=1): questions count as examples
    if d.get('modus') == 'anfrage':
        mail = str(d.get('mail') or '').strip()
        if len(mail) < 20:
            return 400, {'fehler': 'Please paste the message.'}
        return 200, g.anfrage(mail, str(d.get('hinweis') or ''))
    messages = d.get('messages') or []
    if not isinstance(messages, list):
        return 400, {'fehler': 'messages missing'}
    sp = str(d.get('sprache') or 'en')[:2]
    if not g.erlaubt('browser'):
        return 200, {'text': g.GRENZE_TEXT.get(sp, g.GRENZE_TEXT['en']), 'grenze': True}
    a = g.frage(messages, heute=str(d.get('heute', ''))[:10], sprache=sp, seite=str(d.get('seite', ''))[:80])
    letzte = next((str(m.get('content', '')) for m in reversed(messages) if m.get('role') == 'user'), '')
    g.merke('', {'frage': letzte[:g.HOECHSTENS_ZEICHEN], 'antwort': a['text'][:2000], 'belegt': a.get('belegt', True), 'thema': a.get('thema', ''),
                 'sprache': a.get('sprache', sp), 'finder': bool(a.get('maske')), 'seite': str(d.get('seite', ''))[:80]})
    return 200, a


def anfrage(methode, was, query='', roh='', probe=False):
    """One request like server.py: returns JSON text {"status": …, "daten": …}."""
    try:
        status, daten = _anfrage(methode, was, query, roh, probe)
    except ValueError as e:
        t = str(e.args[0]) if e.args else str(e)
        status, daten = (409 if t.startswith('KONFLIKT') else 400), {'fehler': t}
    except Exception as e:  # noqa: BLE001
        try:
            rez().fehler_merken('SERVER · ' + type(e).__name__ + ': ' + str(e)[:300])
        except Exception:  # noqa: BLE001
            pass
        status, daten = 500, {'fehler': 'SERVER · ' + type(e).__name__ + ': ' + str(e)[:200]}
    return json.dumps({'status': status, 'daten': daten}, ensure_ascii=False)


def _anfrage(methode, was, query, roh, probe):
    if methode == 'GET':
        if was == 'haus':
            return 200, {k: HAUS.get(k) for k in ('namen', 'haus', 'ort', 'brief', 'mail', 'support', 'press', 'sales', 'marketing', 'website', 'arten', 'sprachen')}
        if was == 'gast':
            g = gast()
            return 200, {'ok': True, 'modell': 'demo', 'ki': False, 'wissen_zeichen': len(g.WISSEN), 'stand': g.HAUS.get('stand', '')}
        if was == 'export':
            return 200, {'zip': base64.b64encode(rez().export_zip()).decode('ascii')}
        return 200, rez().get(was, parse_qs(query or ''))
    try:
        d = json.loads(roh or '{}')
    except ValueError:
        return 400, {'fehler': 'FORM · The request is not readable JSON.'}
    if not isinstance(d, dict):
        return 400, {'fehler': 'FORM · The request must be an object.'}
    if was == 'gast':
        return _gast_post(d, probe)
    return 200, rez().post(was, d)


def stand():
    """All data files as {path: text} for localStorage (without backups and ZIPs)."""
    aus = {}
    for wurzel, ordner, dateien in os.walk(DATEN):
        ordner[:] = [o for o in ordner if o not in ('sicherung', 'dateien')]
        for f in dateien:
            if f.endswith(('.gut', '.neu', '.alt', '.zip')) or f.startswith('.'):
                continue
            p = os.path.join(wurzel, f)
            try:
                aus[os.path.relpath(p, DATEN)] = open(p, encoding='utf-8').read()
            except (OSError, UnicodeDecodeError):
                pass
    return json.dumps(aus, ensure_ascii=False, sort_keys=True)


def zurueck(text):
    """Puts the data of an earlier visit back (from localStorage)."""
    try:
        d = json.loads(text or '{}')
    except ValueError:
        return 0
    n = 0
    for rel, inhalt in d.items():
        if rel.startswith(('/', '..')) or '/../' in rel:
            continue
        p = os.path.join(DATEN, rel)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        open(p, 'w', encoding='utf-8').write(inhalt); n += 1
    return n


def ersetzen(text):
    """Another tab of the demo (check page, chat window) saved newer data: take them over before the next request."""
    import shutil
    shutil.rmtree(DATEN, ignore_errors=True)
    os.makedirs(DATEN, exist_ok=True)
    return zurueck(text)

dateien._gast/anschluss.py:
"""Connection of Chat Team to the existing txtme chat (online part _cloud/txtme-quellen/backstage-online, Vercel):
  /api/fragen   every question with answer, «belegt» false where the chat had no answer, «erledigt»
  /api/eingang  what customers send through the site (waiting list, press, partner, support, message)
Both deliver {…:[{id, zeit, …}]} with ids «fragen/JJJJ-MM-TT/….json» and «eingang/JJJJ-MM-TT/….json» (the same shape this tool uses).

Switch haus.json → online.an: false (default, AUFTRAG rules 5 and 6) reads the probes in proben/ (same format, recorded answers)
and never calls anything; true fetches the real lists with GAST_GEHEIM from the environment and reports «erledigt» back.
holen() is the only place that knows the online addresses; rezeption.py maps the entries into its own files."""
import datetime, json, os, urllib.error, urllib.request

HIER = os.path.dirname(os.path.abspath(__file__))
WURZEL = os.path.dirname(HIER)


def haus():
    try:
        return json.load(open(os.path.join(WURZEL, 'haus.json'), encoding='utf-8'))
    except (OSError, ValueError):
        return {}


def an():
    return bool((haus().get('online') or {}).get('an')) and bool(os.environ.get('GAST_GEHEIM'))


def _jetzt():
    try:
        from zoneinfo import ZoneInfo
        return datetime.datetime.now(ZoneInfo('Europe/Amsterdam'))
    except Exception:  # noqa: BLE001
        return datetime.datetime.now().astimezone()


def zeit_von(vor, jetzt=None):
    """«vor» [days, hour, minute] → ISO time in the past (probes always look current)."""
    jetzt = jetzt or _jetzt()
    tage, h, m = vor
    z = (jetzt - datetime.timedelta(days=tage)).replace(hour=h, minute=m, second=0, microsecond=0)
    if z > jetzt:
        z -= datetime.timedelta(days=1)
    return z.isoformat(timespec='seconds')


def _probe(name):
    try:
        return json.load(open(os.path.join(WURZEL, 'proben', name), encoding='utf-8'))
    except (OSError, ValueError):
        return {}


def _online(weg):
    basis = (haus().get('online') or {}).get('basis', '').rstrip('/')
    req = urllib.request.Request(basis + weg, headers={'x-gast-geheim': os.environ.get('GAST_GEHEIM', ''), 'accept': 'application/json'})
    try:
        with urllib.request.urlopen(req, timeout=12) as r:
            return json.load(r)
    except (urllib.error.URLError, OSError, ValueError) as e:
        raise ValueError('ONLINE · The online part of the chat did not answer (' + str(getattr(e, 'code', '') or e)[:80] + ').')


def holen():
    """{'fragen': [...], 'eintraege': [...], 'quelle': 'proben'|'online'} in the online format."""
    if an():
        return {'fragen': (_online('/api/fragen').get('fragen') or []), 'eintraege': (_online('/api/eingang').get('eintraege') or []), 'quelle': 'online'}
    jetzt = _jetzt()
    f, e = _probe('fragen.json'), _probe('eingang.json')
    def mit_zeit(l):
        aus = []
        for x in l:
            x = dict(x)
            if x.get('vor') and not x.get('zeit'):
                x['zeit'] = zeit_von(x.pop('vor'), jetzt)
            x['probe'] = True
            aus.append(x)
        return aus
    return {'fragen': mit_zeit(f.get('fragen') or []), 'eintraege': mit_zeit(e.get('eintraege') or []), 'quelle': 'proben'}


def zurueckmelden(art, online_id, erledigt):
    """«erledigt»/«offen» back to the online part (fragen.js / eingang.js: POST {tun, id}). Off: nothing happens, the tool keeps its own state."""
    if not an() or not online_id or online_id.startswith('probe-'):
        return False
    basis = (haus().get('online') or {}).get('basis', '').rstrip('/')
    weg = '/api/fragen' if art == 'fragen' else '/api/eingang'
    req = urllib.request.Request(basis + weg, data=json.dumps({'tun': 'erledigt' if erledigt else 'offen', 'id': online_id}).encode('utf-8'), method='POST',
                                 headers={'content-type': 'application/json', 'x-gast-geheim': os.environ.get('GAST_GEHEIM', '')})
    try:
        urllib.request.urlopen(req, timeout=8).close()
        return True
    except (urllib.error.URLError, OSError):
        return False

dateien._gast/gedaechtnis.py:
"""What the chat knows · Chat Team, txtme.social (copy of _gast/gedaechtnis.py of La Réception of the hotel template, Robert 16.10.2026:
«so eine Art Gehirn, was man sich anschauen kann»). Source of the knowledge here: gast_wissen.txt of the txtme chat (wording of the
English pages of the shop and the catalogue); areas and texts in English for Marouan's team; no name prompt (fixed team name).

Everything the chat knows about txtme.social in one place, readable and correctable for the team:
  Basis        gast_wissen.txt (pages of the website + catalogue), split into sections (page → heading). This file stays unchanged,
               the team lays corrections over it: rephrase a section, hide it, or back to the website.
  Added        Entries of the team (area, title, text, valid until) and entries from links: the page is read in the background,
               the model pulls out only what stands there, the entries apply at once and are marked «from link» with date.
               Without the model (demo) links and files are refused with a clear message; own text with an area goes straight in.
  History      Every change with time, so the team sees what came when.

Effect in the chat: anweisung(basis) puts the corrections at exactly the place of KNOWLEDGE (by position in the text, not by search,
because equal sections occur several times) and appends the additions as a block that wins in case of contradiction.
Expired entries (valid until before today) no longer go into the chat but stay visible.

Storage: daten/gedaechtnis/ (korrekturen.json · fakten.json · eintraege.json · links.json · offen.json · verlauf.json). Local only (server.py)."""
import base64, datetime, hashlib, html, ipaddress, json, os, re, socket, threading, time, urllib.error, urllib.parse, urllib.request

HIER = os.path.dirname(os.path.abspath(__file__))
DATEN = os.path.join(os.environ.get('REZEPTION_DATEN') or os.path.join(os.path.dirname(HIER), 'daten'), 'gedaechtnis')
TEAM = 'Team txtme.social'
try:
    import anschluss as _A
    TEAM = (_A.haus().get('namen') or {}).get('team', TEAM)
except Exception:  # noqa: BLE001
    pass
SCHLOSS = threading.RLock()
QUELLEN = (('gast_wissen.txt', 'KNOWLEDGE'),)
BEREICHE = ['The company', 'The app', 'Merch & pieces', 'Shipping & payment', 'Press', 'Contact', 'Events', 'Questions & answers']
# Page of the website → area
SEITE_BEREICH = [(r'Page: (Home|About)', 'The company'), (r'Page: (Merch|Accessories|Add-ons)|^CATALOGUE', 'Merch & pieces'),
                 (r'Page: Shipping', 'Shipping & payment'), (r'Page: Press', 'Press'), (r'Page: (Support|Security|Cookie)', 'Contact')]
UNTERLAGE_NAME = {}
PREISZEILE = re.compile(r'^\s*All prices in', re.I)


# ---------------------------------------------------------------- Dateien
def _pfad(n):
    return os.path.join(DATEN, n)

def _lies(n, standard):
    try:
        return json.load(open(_pfad(n), encoding='utf-8'))
    except (OSError, ValueError):
        return standard

def _schreib(n, d):
    os.makedirs(DATEN, exist_ok=True)
    tmp = _pfad(n) + '.neu'
    json.dump(d, open(tmp, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    os.replace(tmp, _pfad(n))

def _jetzt():
    try:
        from zoneinfo import ZoneInfo
        return datetime.datetime.now(ZoneInfo('Europe/Amsterdam')).isoformat(timespec='seconds')
    except Exception:  # noqa: BLE001
        return datetime.datetime.now().astimezone().isoformat(timespec='seconds')

def _heute():
    return _jetzt()[:10]

def _merke(art, titel, bereich='', ref='', wer='Team', mehr=''):
    with SCHLOSS:
        v = _lies('verlauf.json', [])
        v.append({'zeit': _jetzt(), 'art': art, 'titel': titel[:160], 'bereich': bereich, 'ref': ref, 'wer': wer, 'mehr': mehr[:300]})
        _schreib('verlauf.json', v[-2000:])


# ---------------------------------------------------------------- Grundlage in Abschnitte zerlegen
def _schoen(t):
    """Überschriften aus dem Seitenbau: «Zimmer& Suiten.» → «Zimmer & Suiten», «Aare.Das» → «Aare. Das»."""
    t = re.sub(r'(\S)&', r'\1 &', t.strip())
    t = re.sub(r'([a-zäöü»])\.([A-ZÄÖÜ«])', r'\1. \2', t)
    return t.rstrip('.').strip() or '…'

_KOEPFE = {}

def _koepfe():
    """Überschriften der gebauten Seiten mit Wortgrenzen ({ohne Leerzeichen: Überschrift}); im Wissen sind die Zeilen der Überschrift zusammengeklebt."""
    if _KOEPFE:
        return _KOEPFE
    web = os.path.dirname(HIER)
    for f in os.listdir(web):
        if not f.endswith('.html'):
            continue
        try:
            s = open(os.path.join(web, f), encoding='utf-8').read()
        except OSError:
            continue
        for h in re.findall(r'<h[1-3][^>]*>(.*?)</h[1-3]>', s, flags=re.S):
            t = re.sub(r'<span class="z"[^>]*>|<br\s*/?>', ' ', h)
            t = re.sub(r'\s+', ' ', html.unescape(re.sub(r'<[^>]+>', '', t))).strip()
            if 2 < len(t) < 160:
                _KOEPFE.setdefault(re.sub(r'\s', '', t), t)
    _KOEPFE.setdefault('', '')
    return _KOEPFE

def _kopf_schoen(roh):
    k = re.sub(r'\s', '', roh)
    if not k:
        return _schoen(roh)
    beste = ''
    for schl, t in _koepfe().items():
        if schl and k.startswith(schl) and len(schl) > len(beste):
            beste = schl
    return _schoen(_koepfe()[beste]) if beste and len(beste) >= 4 else _schoen(roh)

def _block_name(kopf):
    m = re.match(r'Page: (.+?) \((/[^)]*)\)', kopf)
    if m:
        return 'Website', _schoen(m.group(1)), m.group(2)
    if kopf.startswith('CATALOGUE'):
        return 'Catalogue', 'Catalogue (every piece with price, sizes, colours, stock)', '/merch/'
    return 'Grundlage', kopf[:80], ''

def _bereich(kopf):
    for muster, b in SEITE_BEREICH:
        if re.search(muster, kopf):
            return b
    return 'The company'

_CACHE = {}

def abschnitte():
    """Liste aller Abschnitte der Grundlage mit Lage im Text: {aid, datei, von, bis, text, titel, block, art, bereich, stand, quelle}."""
    sig = tuple((n, os.path.getmtime(os.path.join(HIER, n)) if os.path.exists(os.path.join(HIER, n)) else 0) for n, _ in QUELLEN)
    if _CACHE.get('sig') == sig:
        return _CACHE['liste']
    liste = []
    for datei, name in QUELLEN:
        p = os.path.join(HIER, datei)
        if not os.path.exists(p):
            continue
        roh = open(p, encoding='utf-8').read()
        stand = datetime.datetime.fromtimestamp(os.path.getmtime(p)).astimezone().isoformat(timespec='seconds')
        zeilen = roh.splitlines(keepends=True)
        pos, kopf, art, block, ref, teile = 0, '', 'Grundlage', 'Einleitung', '', []
        for z in zeilen:   # Zeilen mit Lage
            teile.append((pos, z)); pos += len(z)
        # Groups: === head === starts a block; ## starts a section (website pages); the catalogue is one section
        stuecke, aktuell = [], None
        def schliesse():
            if aktuell and aktuell['zeilen']:
                stuecke.append(aktuell)
        def unter_kopf(i):   # Zwischenüberschrift einer Unterlage: Grossbuchstaben ohne Einzug (Behandlungen) oder Zeile nach einem Preis vor einem Gericht (Barkarte)
            s = teile[i][1].rstrip('\n')
            if re.fullmatch(r'[A-ZÄÖÜ][A-ZÄÖÜ’\'&\- ]{4,}', s):
                return True
            nach = [teile[j][1] for j in range(i + 1, min(i + 3, len(teile)))]
            return (i > 0 and 'CHF' in teile[i - 1][1] and s.strip() and 'CHF' not in s and '|' not in s and len(nach) == 2
                    and 'CHF' not in nach[0] and '|' not in nach[0] and ('|' in nach[1] or 'CHF' in nach[1]))
        for i, (lage, z) in enumerate(teile):
            s = z.rstrip('\n')
            if s.startswith('=== ') and s.rstrip().endswith('==='):
                schliesse()
                kopf = s.strip('= ').strip(); art, block, ref = _block_name(kopf)
                aktuell = {'kopf': kopf, 'art': art, 'block': block, 'ref': ref, 'zeilen': [], 'ueber': ''}
                continue
            if aktuell is None:
                aktuell = {'kopf': '', 'art': 'Grundlage', 'block': 'Vorbemerkung', 'ref': '', 'zeilen': [], 'ueber': ''}
            neu = (art != 'Unterlage' and s.startswith('## ')) or (art == 'Unterlage' and (PREISZEILE.match(s) and len(aktuell['zeilen']) > 6
                                                                                       or len(aktuell['zeilen']) > 14 and unter_kopf(i)
                                                                                       or len(aktuell['zeilen']) > 40 and i > 0 and 'CHF' in teile[i - 1][1] and 'CHF' not in s))
            if neu and aktuell['zeilen'] and any(x[1].strip() for x in aktuell['zeilen']):
                schliesse()
                aktuell = {'kopf': kopf, 'art': art, 'block': block, 'ref': ref, 'zeilen': [], 'ueber': ''}
            if s.startswith('## ') and not aktuell['ueber']:
                aktuell['ueber'] = s[3:]
            aktuell['zeilen'].append((lage, z))
        schliesse()
        zaehler = {}
        for st in stuecke:
            von = st['zeilen'][0][0]; bis = st['zeilen'][-1][0] + len(st['zeilen'][-1][1])
            text = roh[von:bis]
            if not text.strip():
                continue
            if st['art'] == 'Unterlage':   # Titel: erste Zeile mit Inhalt nach der Preiszeile («Vorspeisen | Starters»)
                kand = [x[1].strip() for x in st['zeilen'] if x[1].strip() and not PREISZEILE.match(x[1]) and not x[1].strip().startswith('All prices')]
                gross = []
                for k in kand[:8]:   # bis zu zwei Überschriften in Grossbuchstaben («SCHWEIZ / SWITZERLAND», «WEISS / WHITE»)
                    k = k.split(' / ')[0].split('|')[0].strip()
                    k = re.sub(r'\s+', ' ', k)
                    if k.isupper() and not re.search(r'\d', k) and len(k) > 2 and k != 'CHF' and k.title() not in gross:
                        gross.append(k.title().replace('’S', '’s'))
                    if len(gross) == 2:
                        break
                titel = ' · '.join(gross) if gross else next((k.split('|')[0].strip() for k in kand if '|' in k), kand[0] if kand else st['block'])
                titel = re.sub(r'\s+', ' ', titel)
            else:
                titel = _kopf_schoen(st['ueber']) if st['ueber'] else (st['block'] if st['art'] != 'Grundlage' else 'Vorbemerkung')
            schl = f"{datei}|{st['kopf']}|{titel}"
            zaehler[schl] = zaehler.get(schl, 0) + 1
            aid = hashlib.sha1(f"{schl}|{zaehler[schl]}".encode('utf-8')).hexdigest()[:12]
            m = re.search(r'(?:abgerufen|gelesen) (?:am )?([0-9]{1,2}\.? ?[0-9A-Za-zä]+\.? ?20[0-9]{2})', st['kopf'])
            liste.append({'aid': aid, 'datei': datei, 'name': name, 'von': von, 'bis': bis, 'text': text.strip('\n'), 'titel': titel[:140],
                          'block': st['block'], 'art': st['art'], 'ref': st['ref'], 'bereich': _bereich(st['kopf'] or datei),
                          'stand': stand, 'gelesen': m.group(1) if m else '', 'pruef': hashlib.sha1(text.encode('utf-8')).hexdigest()[:12]})
    _CACHE.update(sig=sig, liste=liste)
    return liste


# ---------------------------------------------------------------- Steckbrief (steckbrief.json aus steckbrief_bau.py)
def steckbrief():
    """Der Steckbrief mit den Änderungen des Teams je Zeile (fakten.json: fid → {angabe | aus, zeit})."""
    try:
        sb = json.load(open(os.path.join(HIER, 'steckbrief.json'), encoding='utf-8'))
    except (OSError, ValueError):
        return []
    fk = _lies('fakten.json', {})
    for b in sb['bereiche']:
        for g in b['gruppen']:
            for z in g['zeilen']:
                if z['fid'] in fk:
                    z['team'] = fk[z['fid']]
    return sb['bereiche']

def _fakt(fid):
    for b in steckbrief():
        for g in b['gruppen']:
            for z in g['zeilen']:
                if z['fid'] == fid:
                    return b['bereich'], g['gruppe'], z
    raise ValueError('WISSEN · Diese Zeile gibt es nicht mehr. Bitte neu laden.')

def fakten_block():
    l = []
    for b in steckbrief():
        for g in b['gruppen']:
            for z in g['zeilen']:
                t = z.get('team')
                if not t:
                    continue
                if t.get('aus'):
                    l.append(f"[{b['bereich']} · {g['gruppe']}] {z['was']}: no longer applies (was «{z['angabe']}»). Do not mention it; for questions about it point to the team.")
                else:
                    l.append(f"[{b['bereich']} · {g['gruppe']}] {z['was']}: {t['angabe']} (corrected by the team on {t['zeit'][:10]}, was «{z['angabe']}»)")
    if not l:
        return ''
    return ('\n\nCORRECTED BY THE TEAM (counts before KNOWLEDGE; if KNOWLEDGE says otherwise, that is outdated):\n' + '\n'.join(l))


# ---------------------------------------------------------------- Wirkung im Chat
def _ergaenzt_aktiv():
    h = _heute()
    return [e for e in _lies('eintraege.json', []) if not e.get('aus') and (not e.get('gueltig_bis') or e['gueltig_bis'] >= h)]

def neue_texte():
    """{datei: Text mit Berichtigungen des Teams} nur für Dateien mit Berichtigungen."""
    kor = _lies('korrekturen.json', {})
    if not kor:
        return {}
    aus = {}
    for datei, _ in QUELLEN:
        p = os.path.join(HIER, datei)
        if not os.path.exists(p):
            continue
        roh = open(p, encoding='utf-8').read()
        l = sorted((a for a in abschnitte() if a['datei'] == datei and a['aid'] in kor), key=lambda a: -a['von'])
        if not l:
            continue
        t = roh
        for a in l:   # von hinten nach vorn, damit die Lagen stimmen
            k = kor[a['aid']]
            ersatz = '' if k.get('aus') else (f"[Corrected by the txtme.social team on {k['zeit'][:10]}, counts instead of the website:]\n{k['text'].strip()}\n" if k.get('text') else None)
            if ersatz is None:
                continue
            t = t[:a['von']] + ersatz + t[a['bis']:]
        aus[datei] = (roh, t)
    return aus

def ergaenzt_block():
    l = _ergaenzt_aktiv()
    if not l:
        return ''
    def zeile(e):
        q = e.get('quelle') or {}
        herkunft = f"from {q.get('url')}, read on {q.get('gelesen', '')[:10]}" if q.get('art') == 'link' else f"by the team on {(e.get('geaendert') or e.get('zeit'))[:10]}"
        return (f"[{e.get('bereich', '')}] {e.get('titel', '')}" + (f" (valid until {e['gueltig_bis']})" if e.get('gueltig_bis') else '') +
                f"\n{e.get('text', '').strip()}\nSource: {herkunft}")
    return ('\n\nADDED BY THE TEAM (counts like KNOWLEDGE; if something here contradicts KNOWLEDGE, this block counts. Entries «from» a link the team '
            'took over from the page of a partner: name the page as the source and, for events, say that times and prices should be checked there):\n'
            + '\n\n'.join(zeile(e) for e in l))

def anweisung(basis):
    """Die Anweisung des Chats mit allem, was das Team berichtigt und ergänzt hat."""
    t = basis
    for datei, (alt, neu) in neue_texte().items():
        if t.count(alt) == 1:
            t = t.replace(alt, neu)
    return t + fakten_block() + ergaenzt_block()

def wissen_text(wissen):
    """KNOWLEDGE (gast_wissen.txt) with corrections and additions, for the draft of the reply mails."""
    nt = neue_texte().get('gast_wissen.txt')
    return (nt[1] if nt and nt[0] == wissen else wissen) + fakten_block() + ergaenzt_block()


# ---------------------------------------------------------------- Link lesen (im Hintergrund)
class _Text(object):
    """Seite → lesbarer Text: Skripte, Stile, Navigation weg, Absätze als Zeilen, JSON-LD (Veranstaltungen) bleibt dabei."""
    @staticmethod
    def aus(roh):
        ld = ' '.join(re.findall(r'<script[^>]+application/ld\+json[^>]*>(.*?)</script>', roh, flags=re.S | re.I))[:6000]
        titel = html.unescape(re.sub(r'\s+', ' ', (re.search(r'<title[^>]*>(.*?)</title>', roh, flags=re.S | re.I) or [None, ''])[1])).strip()
        s = re.sub(r'<(script|style|noscript|svg|nav|footer|header|form|iframe)\b[^>]*>.*?</\1>', ' ', roh, flags=re.S | re.I)
        s = re.sub(r'<br\s*/?>|</(p|div|li|h\d|tr|section|article|dd|dt)>', '\n', s, flags=re.I)
        s = html.unescape(re.sub(r'<[^>]+>', ' ', s))
        s = re.sub(r'[ \t\xa0]+', ' ', s)
        s = '\n'.join(z.strip() for z in s.splitlines() if z.strip())
        return titel, s, ld

def _sicher(url):
    u = urllib.parse.urlparse(url)
    if u.scheme not in ('http', 'https') or not u.hostname:
        raise ValueError('LINK · Please paste a full address with https://.')
    try:
        for info in socket.getaddrinfo(u.hostname, None):
            ip = ipaddress.ip_address(info[4][0])
            if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved:
                raise ValueError('LINK · This address is not publicly reachable.')
    except socket.gaierror:
        raise ValueError('LINK · This address does not exist. Please check it.')
    return url

def _hole(url):
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0 (Macintosh; Intel Mac OS X 14_6) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.6 Safari/605.1.15',
                                               'Accept-Language': 'de-CH,de;q=0.9,en;q=0.7'})
    try:
        with urllib.request.urlopen(req, timeout=25) as r:
            typ = r.headers.get('Content-Type', '')
            roh = r.read(3_000_000)
    except urllib.error.HTTPError as e:
        raise ValueError(f'SEITE · The page answers with error {e.code}. Please check the address or paste the text of the page.')
    except (urllib.error.URLError, socket.timeout, TimeoutError):
        raise ValueError('SEITE · The page was not reachable. Please read it again later or paste the text of the page.')
    if 'pdf' in typ.lower():
        raise ValueError('PDF · A PDF cannot be read here yet. Please copy the text of the PDF into the field.')
    m = re.search(r'charset=([\w-]+)', typ)
    for enc in ([m.group(1)] if m else []) + ['utf-8', 'latin-1']:
        if enc:
            try:
                return roh.decode(enc)
            except (LookupError, UnicodeDecodeError):
                continue
    return roh.decode('utf-8', 'replace')

AUSZUG = """You help the team of txtme.social in Amsterdam keep the knowledge of the chat on the website up to date. The team gives you new material:
its own text, pages from links (an event, a page of a partner), documents (for example a new price list, a programme) or photos (a poster, a notice).
Pull out what a customer of txtme.social wants to know and return it as entries.

Rules:
- Only what stands word for word in the material or is readable on the photo. Add nothing, estimate nothing, no knowledge from outside. If a detail is missing (time, price), leave it out. Leave out what is unreadable.
- If the team writes something itself (TEXT OF THE TEAM), it counts as a statement of the company, even if it is short.
- One entry per event, offer or topic. At most 12 entries; for long programmes or lists the ones most important for customers.
- titel: short, the way a customer would ask («Launch party Amsterdam», «Shipping to Switzerland»).
- text: in English, two to six whole sentences, factual, with date, time, place, price, registration and contact where present. No marketing talk.
- bereich: one from the list. Events with a date are «Events». If the team chose an area (AREA OF THE TEAM), take it.
- gueltig_bis: for events and time-limited statements the last day (YYYY-MM-DD), otherwise null. Year only if it is stated or clearly follows; otherwise null.
- If there is nothing in the material that customers need, return an empty list and in grund one sentence why.
Answer only with the tool «eintraege»."""

WERKZEUG = {'name': 'eintraege', 'description': 'The entries for the knowledge of the chat.',
            'input_schema': {'type': 'object', 'required': ['eintraege', 'grund'], 'additionalProperties': False,
                             'properties': {'grund': {'type': 'string'},
                                            'eintraege': {'type': 'array', 'items': {'type': 'object', 'additionalProperties': False,
                                                          'required': ['bereich', 'titel', 'text', 'gueltig_bis'],
                                                          'properties': {'bereich': {'type': 'string', 'enum': BEREICHE[:-1]},
                                                                         'titel': {'type': 'string'}, 'text': {'type': 'string'},
                                                                         'gueltig_bis': {'type': ['string', 'null']}}}}}}}

_G = None   # das geladene gast.py (für _api und MODELL), gesetzt von rezeption.einbinden

def _ki(koerper, api=None):
    """Aufruf an Claude über gast.py; Fehler des Dienstes (Guthaben, Grenze, Ausfall) als klare Meldung statt «Fehler 400»."""
    try:
        return (api or _G._api)(koerper)
    except urllib.error.HTTPError as e:
        try:
            m = json.loads(e.read().decode('utf-8')).get('error', {}).get('message', '')
        except Exception:  # noqa: BLE001
            m = ''
        if 'usage limit' in m or 'credit' in m.lower():
            raise ValueError('KI-GUTHABEN · The chat has used up its credit for this month and does not answer right now. As soon as it is free again, it continues here.')
        raise ValueError(f'KI · The chat service does not answer right now (error {e.code}). Please try again in a few minutes.')
    except (urllib.error.URLError, socket.timeout, TimeoutError):
        raise ValueError('KI · The chat service was not reachable. Please try again in a few minutes.')

def _gueltig_bis(s):
    return s if isinstance(s, str) and re.fullmatch(r'20\d\d-\d\d-\d\d', s or '') else None


# ---------------------------------------------------------------- Neues Wissen einlesen: Text, Links, Dokumente, Fotos (im Hintergrund)
# Dateien des Teams liegen unter daten/gedaechtnis/dateien/<lid>/ (für «Neu einlesen» und als Beleg). Claude liest PDF und Fotos selbst
# (Inhaltsblöcke document/image), Word-Dateien und Text werden hier zu Text.
BILD = {'image/jpeg', 'image/png', 'image/webp', 'image/gif'}
TEXTART = ('.txt', '.md', '.csv')
URL = re.compile(r'https?://[^\s<>«»"]+')

def _docx_text(roh):
    import io, zipfile
    with zipfile.ZipFile(io.BytesIO(roh)) as z:
        x = z.read('word/document.xml').decode('utf-8', 'replace')
    x = re.sub(r'</w:p>', '\n', x); x = re.sub(r'<w:tab/>', '\t', x)
    return html.unescape(re.sub(r'<[^>]+>', '', x)).strip()

def _bloecke(lid, auftrag):
    """Inhaltsblöcke für Claude aus Text, Links und Dateien; Fehler einzelner Links werden notiert, solange anderes Material da ist."""
    bl, notiz, titel = [], [], ''
    for url in auftrag.get('urls', []):
        try:
            t, text, ld = _Text.aus(_hole(_sicher(url)))
            if len(text) < 200 and not ld:
                raise ValueError('SEITE · Die Seite zeigt ihren Inhalt erst im Browser. Bitte den Text der Seite ins Feld kopieren.')
            titel = titel or t
            bl.append({'type': 'text', 'text': f'SEITE {url} (Titel: {t})' + (f'\nStrukturierte Angaben (JSON-LD): {ld}' if ld else '') + f'\n{text[:40000]}'})
        except ValueError as e:
            notiz.append(re.sub(r'^[A-ZÄÖÜ]+ · ', '', str(e)))
    ordner = _pfad(os.path.join('dateien', lid))
    for f in auftrag.get('dateien', []):
        p = os.path.join(ordner, f['datei'])
        try:
            roh = open(p, 'rb').read()
        except OSError:
            notiz.append(f'{f["name"]} is missing.'); continue
        typ, name = f.get('typ', ''), f['name']
        titel = titel or name
        if typ == 'application/pdf' or name.lower().endswith('.pdf'):
            bl.append({'type': 'text', 'text': f'DOKUMENT {name}:'})
            bl.append({'type': 'document', 'source': {'type': 'base64', 'media_type': 'application/pdf', 'data': base64.b64encode(roh).decode('ascii')}})
        elif typ in BILD:
            bl.append({'type': 'text', 'text': f'FOTO {name}:'})
            bl.append({'type': 'image', 'source': {'type': 'base64', 'media_type': typ, 'data': base64.b64encode(roh).decode('ascii')}})
        elif name.lower().endswith('.docx'):
            bl.append({'type': 'text', 'text': f'DOKUMENT {name}:\n{_docx_text(roh)[:40000]}'})
        elif name.lower().endswith(TEXTART):
            bl.append({'type': 'text', 'text': f'DOKUMENT {name}:\n{roh.decode("utf-8", "replace")[:40000]}'})
        else:
            notiz.append(f'{name}: this kind of file cannot be read.')
    if auftrag.get('text'):
        bl.append({'type': 'text', 'text': 'TEXT OF THE TEAM:\n' + auftrag['text']})
    return bl, notiz, titel

def _auszug(bloecke, bereich, hinweis=''):
    if _G is None:
        raise ValueError('CHAT · The assistant is not loaded yet. Restart server.py.')
    kopf = f'Today is {_heute()}.' + (f'\nAREA OF THE TEAM: {bereich}' if bereich else '') + (f'\nNote of the team: {hinweis}' if hinweis else '')
    a = _ki({'model': _G.MODELL, 'max_tokens': 8000, 'tools': [WERKZEUG], 'system': AUSZUG,
             'messages': [{'role': 'user', 'content': [{'type': 'text', 'text': kopf}] + bloecke}]})
    for b in a.get('content', []):
        if b.get('type') == 'tool_use' and b.get('name') == 'eintraege':
            return b.get('input') or {}
    roh = ''.join(b.get('text', '') for b in a.get('content', []) if b.get('type') == 'text')
    m = re.search(r'\{.*\}', roh, flags=re.S)
    if m:
        try:
            return json.loads(m.group(0))
        except ValueError:
            pass
    raise ValueError('AUSZUG · The material could not be evaluated. Please try again.')

def _setze_job(lid, **k):
    with SCHLOSS:
        ls = _lies('links.json', [])
        for x in ls:
            if x['lid'] == lid:
                x.update(k)
        _schreib('links.json', ls)

def _lauf(lid, auftrag, von=''):
    try:
        bl, notiz, titel = _bloecke(lid, auftrag)
        if not bl:
            raise ValueError('EINGABE · ' + (' '.join(notiz) or 'Nothing to read.'))
        erg = _auszug(bl, auftrag.get('bereich') or '', auftrag.get('hinweis') or '')
        jetzt = _jetzt()
        roh_l = [e for e in (erg.get('eintraege') or []) if isinstance(e, dict) and (e.get('titel') or '').strip() and (e.get('text') or '').strip()][:12]
        urls = auftrag.get('urls') or []
        art = 'link' if urls and not auftrag.get('dateien') and not auftrag.get('text') else 'eingabe'
        with SCHLOSS:
            alle = _lies('eintraege.json', [])
            alt = [e for e in alle if (e.get('quelle') or {}).get('lid') == lid]
            alle = [e for e in alle if (e.get('quelle') or {}).get('lid') != lid]
            wids = []
            for n, e in enumerate(roh_l):
                wid = f'l{lid}-{n}'
                ber = auftrag.get('bereich') if auftrag.get('bereich') in BEREICHE else (e['bereich'] if e.get('bereich') in BEREICHE else 'Events')
                alle.append({'wid': wid, 'bereich': ber, 'titel': e['titel'].strip()[:140], 'text': e['text'].strip()[:3000],
                             'gueltig_bis': _gueltig_bis(e.get('gueltig_bis')), 'zeit': jetzt, 'geaendert': jetzt, 'von': von,
                             'quelle': {'art': art, 'url': urls[0] if urls else '', 'titel': titel[:160], 'gelesen': jetzt, 'lid': lid,
                                        'dateien': [f['name'] for f in auftrag.get('dateien', [])]}})
                wids.append(wid)
            _schreib('eintraege.json', alle)
        _setze_job(lid, status='fertig' if wids else 'leer', fertig=jetzt, wids=wids, titel=titel[:160] or auftrag.get('titel', ''),
                   meldung=' '.join(notiz)[:300] if wids else ((erg.get('grund') or '') + (' ' + ' '.join(notiz) if notiz else ''))[:300])
        if wids:
            herkunft = ', '.join([urllib.parse.urlparse(u).hostname.replace('www.', '') for u in urls] + [f['name'] for f in auftrag.get('dateien', [])]) or 'text of the team'
            _merke('link', f"{len(wids)} {'entry' if len(wids) == 1 else 'entries'} from {herkunft}" + (' (read again)' if alt else ''),
                   roh_l[0].get('bereich', ''), lid, von or 'Team', ' · '.join(e['titel'] for e in roh_l)[:300])
    except Exception as e:  # noqa: BLE001
        m = str(e) if isinstance(e, ValueError) else 'FEHLER · Reading stopped. Please try again.'
        _setze_job(lid, status='fehler', fertig=_jetzt(), meldung=re.sub(r'^[A-ZÄÖÜ]+ · ', '', m)[:300])

GRENZE_DATEI = 20 * 1024 * 1024

def einlesen(text='', dateien=None, bereich='', von='', lid='', hinweis=''):
    """Neues Wissen: Text, Links im Text, Dateien (base64 vom Browser). Ohne Links und Dateien und mit gewähltem Bereich wird der Text
    direkt zur Angabe (geht auch, wenn die KI nicht antwortet). Sonst liest ein Hintergrund-Faden alles und legt die Angaben an.
    Mit lid: denselben Auftrag neu einlesen (gespeicherte Dateien und Text)."""
    with SCHLOSS:
        ls = _lies('links.json', [])
    if lid:
        alt = next((x for x in ls if x['lid'] == lid), None)
        if not alt:
            raise ValueError('WISSEN · This job no longer exists.')
        auftrag = alt.get('auftrag') or {'urls': [alt['url']] if alt.get('url') else [], 'text': '', 'dateien': [], 'bereich': ''}
    else:
        text = (text or '').strip()
        if len(text) > 60000:
            raise ValueError(f'LAENGE · The text has {len(text):,} characters, at most 60,000 fit. Nothing was saved: shorten it and try again.')
        urls = list(dict.fromkeys(u.rstrip('.,;)') for u in URL.findall(text)))[:5]
        rest = URL.sub('', text).strip()
        dateien = [f for f in (dateien or []) if isinstance(f, dict) and f.get('daten')][:10]
        bereich = bereich if bereich in BEREICHE else ''
        if not urls and not dateien and len(rest) < 3:
            raise ValueError('EINGABE · Please write something, paste a link or add a file.')
        if not urls and not dateien and bereich:   # eigener Text mit Bereich: direkt ins Wissen
            erste = re.split(r'(?<=[^\d\s][.!?])\s+(?=[A-ZÄÖÜ«])|\n', rest, maxsplit=1)[0].strip().rstrip('.')
            titel = erste if len(erste) <= 70 else erste[:67].rsplit(' ', 1)[0] + ' …'
            return {'direkt': post('wissen_eintrag', {'bereich': bereich, 'titel': titel, 'text': rest, 'von': von})['eintrag']}
        if _G is None or not getattr(_G, 'KI', False):   # links, documents and photos need the model: in the demo an honest message instead of invented entries
            import probe_ki
            raise ValueError(probe_ki.einlesen_fehler())
        for u in urls:
            _sicher(u)
        lid = hashlib.sha1(f'{text}|{time.time()}'.encode('utf-8')).hexdigest()[:8]
        ordner = _pfad(os.path.join('dateien', lid))
        abgelegt = []
        for n, f in enumerate(dateien):
            try:
                roh = base64.b64decode(f['daten'].split(',', 1)[-1])
            except Exception:  # noqa: BLE001
                raise ValueError(f'DATEI · {f.get("name", "file")} could not be read.')
            if len(roh) > GRENZE_DATEI:
                raise ValueError(f'DATEI · {f.get("name", "file")} is larger than 20 MB.')
            name = re.sub(r'[^\w.\- äöüÄÖÜ]', '_', str(f.get('name') or f'datei-{n}'))[:100]
            os.makedirs(ordner, exist_ok=True)
            datei = f'{n:02d}-{name}'
            open(os.path.join(ordner, datei), 'wb').write(roh)
            abgelegt.append({'name': name, 'typ': str(f.get('typ') or '')[:60], 'datei': datei, 'groesse': len(roh)})
        auftrag = {'urls': urls, 'text': rest, 'dateien': abgelegt, 'bereich': bereich, 'hinweis': hinweis[:400]}
    titel = auftrag['dateien'][0]['name'] if auftrag.get('dateien') else (urllib.parse.urlparse(auftrag['urls'][0]).hostname or '').replace('www.', '') if auftrag.get('urls') else (auftrag.get('text') or '')[:60]
    with SCHLOSS:
        ls = [x for x in _lies('links.json', []) if x['lid'] != lid]
        eintrag = {'lid': lid, 'url': (auftrag.get('urls') or [''])[0], 'zeit': _jetzt(), 'status': 'liest', 'titel': titel, 'wids': [], 'von': von, 'auftrag': auftrag,
                   'art': 'eingabe' if auftrag.get('dateien') or auftrag.get('text') else 'link'}
        ls.append(eintrag)
        _schreib('links.json', ls)
    threading.Thread(target=_lauf, args=(lid, auftrag, von), daemon=True).start()
    return {'link': eintrag}

def link_lesen(url, text='', hinweis='', lid='', von=''):
    """Alter Weg (nur ein Link oder eingefügter Text) über einlesen()."""
    if lid:
        return einlesen(lid=lid, von=von)['link']
    url = (url or '').strip()
    if url and not re.match(r'https?://', url):
        url = 'https://' + url
    return einlesen(text=(url + '\n' + (text or '')).strip(), von=von, hinweis=hinweis).get('link')


# ---------------------------------------------------------------- Schnittstelle (/reception/api/wissen…)
def get(was, q=None):
    if was == 'wissen':
        kor = _lies('korrekturen.json', {})
        l = []
        for a in abschnitte():
