def _feld(d, k, grenze, name):
    """Text of a field the team typed: never cut short without a word (Abnahme 06.11.2026 Fund 4)."""
    t = str(d.get(k) or '').strip()
    if len(t) > grenze:
        raise ValueError(f'LAENGE · {name} has {len(t):,} characters, at most {grenze:,} fit. Nothing was saved: shorten it and try again.')
    return t

def _von(d):
    """Who entered it: the fixed team name (Fehlerbuch 20.10.2026, no «who is working here?» prompt before delivery); a name sent along is kept."""
    v = re.sub(r'\s+', ' ', str(d.get('von') or '')).strip()[:60]
    return v if len(v) >= 2 else TEAM

def _abschnitt(aid):
    a = next((x for x in abschnitte() if x['aid'] == aid), None)
