            n = sum(1 for e in alle if (e.get('quelle') or {}).get('lid') == lid)
            _schreib('eintraege.json', [e for e in alle if (e.get('quelle') or {}).get('lid') != lid])
            import shutil
            shutil.rmtree(_pfad(os.path.join('dateien', re.sub(r'\W', '', str(lid)))), ignore_errors=True)
        _merke('entfernt', f"Link {urllib.parse.urlparse(x.get('url') or '').hostname or 'text'} with {n} {'entry' if n == 1 else 'entries'}", 'Events', lid)
        return {'ok': True}
    if was == 'wissen_probe':        # Frage an den Chat mit dem jetzigen Wissen, ohne Protokoll
        f = _feld(d, 'frage', 600, 'The question')
        if len(f) < 3:
            raise ValueError('EINGABE · Please enter a question.')
        if _G is None:
            raise ValueError('CHAT · The assistant is not loaded yet. Restart server.py.')
        roh = _G._api
