        try:
            a = _G.frage([{'role': 'user', 'content': f}], heute=_heute(), sprache='en')
        finally:
            _G._api = roh
        return {'text': a.get('text', ''), 'belegt': a.get('belegt', True)}
    raise ValueError('WISSEN · Unknown request.')

dateien._gast/rezeption.py:
"""Chat Team · txtme.social. The tool of the team behind the txtme chat (copy of La Réception of the hotel template, _gast/rezeption.py,
Robert 12.10.2026; here in the txtme dress and attached to the existing chat).

Two things come from the chat and the website:
  Inbox        What customers send through the site and the chat window (waiting list, press, partner, support, message): the online part
               keeps them under /api/eingang (backstage-online/api/eingang.js). The team gets a draft reply in the tone of txtme.social,
               changes it and sends it itself. Nothing is sent from here.
  Asked        Every question with answer (/api/fragen, backstage-online/api/fragen.js). Where the chat had no answer (tool «nicht_belegt»),
               the team adds it once; from then on the chat answers with it (block «ADDED BY THE TEAM» in the instruction).

Storage: files under daten/, in the same layout as the online storage (Vercel Blob, fragen.js / eingang.js):
  fragen/JJJJ-MM-TT/<zeit>-<zufall>.json · anfragen/JJJJ-MM-TT/<zeit>-<zufall>.json · nachgetragen.json · status.json · fehler.jsonl
Entries older than twelve months are deleted. Every write keeps the last good copy as .gut (Master F36), reading falls back to it.

Bound by server.py: rezeption.einbinden(gast_modul) hooks into _gast/gast.py without changing that file. anschluss.py brings the entries
of the online part (switched off: the probes in proben/)."""
import datetime, glob, hashlib, html, io, json, os, random, re, shutil, threading, time, zipfile
try:   # «What the chat knows» (16.10.2026, local): corrections and additions of the team to the knowledge
    import gedaechtnis
except ImportError:
    gedaechtnis = None
import anschluss

HIER = os.path.dirname(os.path.abspath(__file__))
WURZEL = os.path.dirname(HIER)
DATEN = os.environ.get('REZEPTION_DATEN') or os.path.join(WURZEL, 'daten')
SCHLOSS = threading.RLock()   # re-entrant: beispiele() files entries through lege_anfrage() under the same lock
LOKAL = threading.local()
HAUS = anschluss.haus()
ARTEN = HAUS.get('arten') or {'support': 'Support', 'warteliste': 'Waiting list', 'presse': 'Press', 'partner': 'Partner & business', 'newsletter': 'Newsletter', 'nachricht': 'Message'}
# From which address the team answers a kind of request (support page of txtme.social)
ABSENDER = {'presse': HAUS.get('press', 'press@txtme.social'), 'partner': HAUS.get('sales', 'sales-b2b@txtme.social')}
SPRACHEN = tuple(HAUS.get('sprachen') or ('en', 'de', 'nl', 'fr', 'es'))
TEAM = (HAUS.get('namen') or {}).get('team', 'Team txtme.social')   # fixed name in the protocol, no «who is working here?» prompt (Fehlerbuch 20.10.2026)
# Topics for «What was asked»: word lists in the customers' languages, the first match wins
THEMEN = [('Orders & shipping', r'order|parcel|ship|deliver|track|versand|liefer|bestell|verzend|levering|livraison|envío|envio|country|countries|switzerland|belgium|customs|zoll'),
          ('Sizes & pieces', r'size|sizes|fit|small|large|medium|material|cotton|colour|color|black|white|shirt|tee|tank|top|cap|hat|bag|piece|merch|stock|print|grösse|groesse|größe|farbe|maat|taille|talla'),
          ('Returns & payment', r'return|refund|exchange|withdraw|pay|payment|klarna|ideal|wero|mollie|card|invoice|price|vat|zahl|rückgabe|umtausch|retour|betal|paiement|pago'),
          ('The app & the code', r'\bapp\b|code|qr|scan|profile|feed|stories|connect|launch|store|android|ios|iphone|algorithm|message|encrypt|vault|memories'),
          ('Press & partners', r'press|interview|journalist|magazine|partner|business|b2b|café|cafe|bar|venue|collab|wholesale|bulk|crew|team order|presse|zeitung'),
          ('Account & privacy', r'account|login|password|privacy|data|delete|gdpr|cookie|tracking|safety|report|datenschutz|konto'),
          ('Contact & company', r'phone|call|address|office|amsterdam|founder|company|who runs|contact|e-?mail|mail')]
ABDECKEN = [(re.compile(r'[\w.+-]+@[\w-]+\.[\w.-]+'), '[e-mail]'), (re.compile(r'(?:\+|00)?\d[\d\s/().-]{7,}\d'), '[number]')]


# ---------------------------------------------------------------- Files
def _pfad(*t):
    return os.path.join(DATEN, *t)

def _lies(p, standard):
    """Read JSON; a damaged file falls back to the last good copy .gut instead of being read as empty (F36)."""
    try:
        return json.load(open(p, encoding='utf-8'))
    except OSError:
        return standard
    except ValueError:
        try:
            return json.load(open(p + '.gut', encoding='utf-8'))
        except (OSError, ValueError):
            return standard

def _schreib(p, d):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    if os.path.exists(p):
        try:
            shutil.copy2(p, p + '.gut')
        except OSError:
            pass
    tmp = p + '.neu'
    json.dump(d, open(tmp, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    os.replace(tmp, p)

def feld(d, k, grenze, name):
    """Text of a field the team typed: never cut short without a word (Abnahme 06.11.2026 Fund 4). Too long → clear message, nothing is saved."""
    t = str(d.get(k) or '').strip()
    if len(t) > grenze:
        raise ValueError(f'LAENGE · {name} has {len(t):,} characters, at most {grenze:,} fit. Nothing was saved: shorten it and try again.')
    return t

def _jetzt():
    try:
        from zoneinfo import ZoneInfo
        return datetime.datetime.now(ZoneInfo('Europe/Amsterdam'))
    except Exception:  # noqa: BLE001
        return datetime.datetime.now().astimezone()

def _neue_id(art, zeit=None):
    zeit = zeit or _jetzt().isoformat(timespec='seconds')
    return zeit, f'{art}/{zeit[:10]}/{zeit.replace(":", "-").replace("+", "_")}-{random.randrange(36**6):06x}.json'

def _gueltig(id_, art):
    return bool(re.fullmatch(art + r'/\d{4}-\d{2}-\d{2}/[\w.-]+\.json', id_ or '')) and os.path.exists(_pfad(id_))

def _alle(art):
    l = []
    for f in sorted(glob.glob(_pfad(art, '*', '*.json')), reverse=True):
        d = _lies(f, None)
        if d:
            d['id'] = os.path.relpath(f, DATEN)
            l.append(d)
    return l

def aufraeumen():
    """Delete entries older than twelve months (whole day folders)."""
    grenze = (datetime.date.today() - datetime.timedelta(days=365)).isoformat()
    n = 0
    for art in ('fragen', 'anfragen'):
        for o in glob.glob(_pfad(art, '*')):
            if os.path.basename(o) < grenze:
                shutil.rmtree(o, ignore_errors=True); n += 1
    return n


# ---------------------------------------------------------------- Filing (from the chat)
def thema_von(text):
    t = (text or '').lower()
    for name, muster in THEMEN:
        if re.search(muster, t):
            return name
    return 'Other questions'

def lege_frage(daten, zeit=None):
    for muster, ersatz in ABDECKEN:
        daten['frage'] = muster.sub(ersatz, daten.get('frage', ''))
    zeit, id_ = _neue_id('fragen', zeit)
    e = {'zeit': zeit, 'frage': str(daten.get('frage', ''))[:600], 'antwort': str(daten.get('antwort', ''))[:2000], 'belegt': daten.get('belegt') is not False,
         'thema': str(daten.get('thema', ''))[:80], 'gruppe': thema_von(daten.get('frage', '')), 'sprache': str(daten.get('sprache', 'en'))[:2],
         'finder': bool(daten.get('finder')), 'seite': str(daten.get('seite', ''))[:80], 'anfrage': daten.get('anfrage') or '', 'online_id': str(daten.get('online_id') or '')[:120]}
    if daten.get('beispiel'):
        e['beispiel'] = True; e['probe'] = True
    with SCHLOSS:
        _schreib(_pfad(id_), e)
    if random.random() < 0.05:
        aufraeumen()
    return id_

def lege_anfrage(eingabe, gespraech, sprache, verlauf, zeit=None):
    """Files a request. If the same kind comes again in the same conversation (the customer adds something), it is completed, not doubled."""
    art = eingabe.get('art') if eingabe.get('art') in ARTEN else 'nachricht'
    with SCHLOSS:
        for a in _alle('anfragen')[:80]:
            if gespraech and a.get('gespraech') == gespraech and a.get('art') == art and a.get('status') != 'erledigt':
                for k in ('name', 'kontakt', 'anliegen', 'seite'):
                    if eingabe.get(k) not in (None, ''):
                        a[k] = eingabe[k]
                a['verlauf'] = verlauf; a['entwurf'] = None; a['geaendert'] = _jetzt().isoformat(timespec='seconds')
                id_ = a.pop('id'); _schreib(_pfad(id_), a)
                return id_
        zeit, id_ = _neue_id('anfragen', zeit)
        _schreib(_pfad(id_), {'zeit': zeit, 'art': art, 'name': str(eingabe.get('name') or '')[:120], 'kontakt': str(eingabe.get('kontakt') or '')[:160],
                              'anliegen': str(eingabe.get('anliegen') or '')[:2000], 'seite': str(eingabe.get('seite') or '')[:80], 'consent': bool(eingabe.get('consent')),
                              'sprache': sprache, 'gespraech': gespraech, 'verlauf': verlauf, 'status': 'neu', 'entwurf': None, 'fassung': 0,
                              'online_id': str(eingabe.get('online_id') or '')[:120], **({'beispiel': True, 'probe': True} if eingabe.get('probe') else {})})
        return id_


# ---------------------------------------------------------------- Examples in the inbox (from the online part or its probes)
BEISPIEL_STAND = 1   # 1: six probe requests with drafts, nine probe questions, three example answers (06.11.2026)


def _stand(marke):
    """Which example level lies in this data folder: 0 = none yet."""
    if not os.path.exists(marke):
        return 0
    return int(_lies(marke, {}).get('stand') or 1)


def _quelle(e):
    """Hash of the text the reading copy was made from: changes the team the letter, the copy is outdated."""
    return hashlib.sha1(((e.get('betreff') or '') + '\n' + (e.get('text') or '')).encode('utf-8')).hexdigest()[:12]


def uebersetzen(id_):
    """English reading copy of a letter in another language and of its chat conversation (Robert 16.10.2026: the colleague must be able to see
    what the letter says before sending it). Stored, valid until the letter changes. Without the model: the original, marked (probe_ki)."""
    if not _gueltig(id_, 'anfragen'):
        raise ValueError('ANFRAGE · This request no longer exists.')
    a = _lies(_pfad(id_), {})
    e = a.get('entwurf') or {}
    if not e.get('text'):
        raise ValueError('TRANSLATE · There is no letter yet.')
    q = _quelle(e)
    if (e.get('englisch') or {}).get('quelle') == q and a.get('verlauf_en') is not None:
        return {'englisch': e['englisch'], 'verlauf_en': a['verlauf_en']}
    if _G is None:
        raise ValueError('CHAT · The assistant is not loaded yet.')
    verlauf = [v.get('text', '') for v in a.get('verlauf') or []]
    if not getattr(_G, 'KI', False):
        import probe_ki
        d = probe_ki.uebersetzen(e.get('betreff', ''), e['text'], verlauf)
    else:
        eingabe = json.dumps({'betreff': e.get('betreff', ''), 'text': e['text'], 'verlauf': verlauf}, ensure_ascii=False)
        antwort = _G._api({'model': _G.MODELL, 'max_tokens': 6000, 'system': UEBERSETZEN, 'messages': [{'role': 'user', 'content': eingabe}]})
        roh = ''.join(b.get('text', '') for b in antwort.get('content', []) if b.get('type') == 'text').strip()
        roh = re.sub(r'^```(?:json)?\s*|\s*```$', '', roh)
        try:
            d = json.loads(roh[roh.index('{'):roh.rindex('}') + 1])
        except (ValueError, json.JSONDecodeError):
            raise ValueError('TRANSLATE · The translation came back incomplete. Please try again.')
    with SCHLOSS:
        a = _lies(_pfad(id_), {})
        a['entwurf']['englisch'] = {'betreff': str(d.get('betreff') or ''), 'text': str(d.get('text') or ''), 'quelle': q, 'demo': bool(d.get('demo'))}
        vd = d.get('verlauf') if isinstance(d.get('verlauf'), list) else []
        a['verlauf_en'] = [str(x) for x in vd][:len(verlauf)] if len(vd) == len(verlauf) else a.get('verlauf_en') or []
        _schreib(_pfad(id_), a)
    return {'englisch': a['entwurf']['englisch'], 'verlauf_en': a['verlauf_en']}


UEBERSETZEN = """You translate, for the team of txtme.social, a reply letter to a customer and the chat conversation the customer had, into English.
The translation is only for the team to read along and is never sent. Translate exactly and completely, leave nothing out, add nothing.
Parts in square brackets stay in square brackets, translated. Names, addresses, numbers and prices stay as they are.
Answer only with JSON: {"betreff": "…", "text": "…", "verlauf": ["…", …]} – «verlauf» has exactly as many entries as the input, in the same order."""


def beispiele():
    """Requests from the online part (or its probes, proben/eingang.json) go into the inbox as the examples of the demo (Robert 13.10.2026,
    M27). Each data folder remembers the level in beispiele.json; a new level only adds what is new, deleted examples do not come back.
    If a real request already lies there the first time, the inbox stays as it is. Names and addresses of the probes are invented (example.com)."""
    marke = _pfad('beispiele.json')
    if _stand(marke) >= BEISPIEL_STAND and not anschluss.an():
        return 0
    with SCHLOSS:
        stand = _stand(marke)
        if stand >= BEISPIEL_STAND and not anschluss.an():
            return 0
        da = {a.get('online_id'): a for a in _alle('anfragen') if a.get('online_id')}
        if not stand and any(not a.get('beispiel') for a in _alle('anfragen')):
            _schreib(marke, {'angelegt': '', 'anzahl': 0, 'stand': BEISPIEL_STAND})
            return 0
        try:
            quelle = anschluss.holen()
        except ValueError:
            quelle = {'eintraege': [], 'fragen': []}
        n_neu = 0
        for b in quelle.get('eintraege') or []:
            oid = str(b.get('id') or '')
            if not oid or oid in da:
                continue
            zeit = str(b.get('zeit') or _jetzt().isoformat(timespec='seconds'))[:19]
            sp = b.get('sprache') if b.get('sprache') in SPRACHEN else 'en'
            e = {'art': b.get('art'), 'name': b.get('name'), 'kontakt': b.get('email'), 'anliegen': b.get('text'), 'seite': b.get('source'), 'consent': b.get('consent'),
                 'online_id': oid, 'probe': bool(b.get('probe'))}
            verlauf = [{'rolle': r, 'text': t} for r, t in (b.get('verlauf') or [])]
            id_ = lege_anfrage(e, '', sp, verlauf, zeit)
            a = _lies(_pfad(id_), {})
            if b.get('erledigt'):
                a['status'] = 'erledigt'
            if b.get('entwurf'):   # prewritten draft of the probe (no model call)
                ent = b['entwurf']
                a['entwurf'] = {'betreff': ent.get('betreff', ''), 'text': ent.get('text', ''), 'team': ent.get('team', ''), 'absender': ABSENDER.get(a['art'], HAUS.get('support', '')),
                                'zeit': zeit, 'demo': True}
                if ent.get('englisch'):
                    a['entwurf']['englisch'] = dict(ent['englisch'], quelle=_quelle(a['entwurf']))
                if a['status'] == 'neu':
                    a['status'] = 'gelesen'
            if b.get('text_englisch'):
                a['anliegen_en'] = b['text_englisch']
            _schreib(_pfad(id_), a)
            n_neu += 1
        _schreib(marke, {'angelegt': _jetzt().isoformat(timespec='seconds'), 'anzahl': len(quelle.get('eintraege') or []), 'stand': BEISPIEL_STAND, 'quelle': quelle.get('quelle')})
        return n_neu


def beispiel_fragen():
    """Questions from the online part (or its probes, proben/fragen.json) for «What was asked», and example answers of the team
    (gast_beispiel_nachgetragen.json). Level as in beispiele(). The example answers do not go into the chat's knowledge."""
    marke = _pfad('beispiele_fragen.json')
    if _stand(marke) >= BEISPIEL_STAND and not anschluss.an():
        return 0
    with SCHLOSS:
        stand = _stand(marke)
        if stand >= BEISPIEL_STAND and not anschluss.an():
            return 0
        da = {f.get('online_id') for f in _alle('fragen') if f.get('online_id')}
        if not stand and any(not f.get('beispiel') for f in _alle('fragen')):
            _schreib(marke, {'angelegt': '', 'anzahl': 0, 'stand': BEISPIEL_STAND})
            return 0
        try:
            quelle = anschluss.holen()
        except ValueError:
            quelle = {'fragen': []}
        jetzt = _jetzt(); n_neu = 0
        for b in quelle.get('fragen') or []:
            oid = str(b.get('id') or '')
            if not oid or oid in da:
                continue
            zeit = str(b.get('zeit') or jetzt.isoformat(timespec='seconds'))[:19]
            lege_frage({'frage': b.get('frage', ''), 'antwort': b.get('antwort', ''), 'belegt': bool(b.get('belegt', True)), 'thema': b.get('thema', ''),
                        'sprache': b.get('sprache', 'en'), 'finder': bool(b.get('finder')), 'seite': b.get('seite', ''), 'online_id': oid, 'beispiel': bool(b.get('probe'))}, zeit)
            if b.get('erledigt'):
                s = _lies(_pfad('status.json'), {}); fe = set(s.get('fragen_erledigt', [])); fe.add(oid); s['fragen_erledigt'] = sorted(fe)[-5000:]; _schreib(_pfad('status.json'), s)
            n_neu += 1
        ng = nachgetragen()
        if not stand and not any(str(x.get('nid', '')).startswith('beispiel-') for x in ng):
            for n, b in enumerate(_lies(os.path.join(HIER, 'gast_beispiel_nachgetragen.json'), []), 1):
                ng.append({'nid': f'beispiel-{n}', 'frage': b['frage'], 'antwort': b['antwort'], 'zeit': anschluss.zeit_von(b['vor'], jetzt), 'quelle': '', 'beispiel': True})
            _schreib(_pfad('nachgetragen.json'), ng)
        _schreib(marke, {'angelegt': jetzt.isoformat(timespec='seconds'), 'anzahl': len(quelle.get('fragen') or []), 'stand': BEISPIEL_STAND, 'quelle': quelle.get('quelle')})
        return n_neu


# ---------------------------------------------------------------- Added by the team
def nachgetragen():
    return _lies(_pfad('nachgetragen.json'), [])

def wissen_block():
    l = [x for x in nachgetragen() if (x.get('antwort') or '').strip() and not x.get('beispiel')]   # examples are invented, the chat does not say them
    if not l:
        return ''
    return ('\n\nADDED BY THE TEAM (counts like KNOWLEDGE; the txtme.social team wrote these answers itself after customers asked):\n'
            + '\n'.join(f'Question: {x["frage"]}\nAnswer of the team: {x["antwort"]}' for x in l))


# ---------------------------------------------------------------- Binding to _gast/gast.py
_G = None

def einbinden(g):
    """Hooks Chat Team into the loaded module _gast/gast.py: knowledge of the team in the instruction, questions filed here instead of
    at the online storage, questions from «Try the chat» marked as examples."""
    global _G
    _G = g
    os.makedirs(DATEN, exist_ok=True)
    if gedaechtnis:
        gedaechtnis._G = g
    basis = g.ANWEISUNG
    roh_frage, roh_ip = g.frage, g.handler._ip

    def ip(self):
        LOKAL.ip = roh_ip(self)
        # «Try the chat» in Chat Team opens the chat window with ?probe=1: questions from there count as examples (Robert 16.10.2026)
        LOKAL.probe = 'probe=1' in (self.headers.get('referer') or self.headers.get('Referer') or '')
        return LOKAL.ip

    def frage(messages, heute='', sprache='en', seite=''):
        g.ANWEISUNG = (gedaechtnis.anweisung(basis) if gedaechtnis else basis) + wissen_block()   # what the team corrected, added and completed counts from the next question
        return roh_frage(messages, heute=heute, sprache=sprache, seite=seite)

    def merke(host, daten):
        try:
            lege_frage(dict(daten, beispiel=bool(getattr(LOKAL, 'probe', False))))
        except Exception:  # noqa: BLE001  the answer to the customer is not affected
            pass

    roh_erlaubt = g.erlaubt

    def erlaubt(ip_, art='gast'):
        # «Try the chat» in Chat Team is the team trying, not a customer: the brake of the website (20 questions in 10 minutes) does not apply (Abnahme 06.11.2026 Fund 6e)
        if art == 'gast' and getattr(LOKAL, 'probe', False):
            return True
        return roh_erlaubt(ip_, art)

    g.frage, g.merke, g.handler._ip, g.erlaubt = frage, merke, ip, erlaubt
    roh_post = g.handler.do_POST

    def do_post(self):
        LOKAL.probe = False
        return roh_post(self)
    g.handler.do_POST = do_post
    return g


# ---------------------------------------------------------------- Draft
def entwurf(id_, hinweis=''):
    if not _gueltig(id_, 'anfragen'):
        raise ValueError('ANFRAGE · This request no longer exists.')
    if _G is None:
        raise ValueError('CHAT · The assistant is not loaded yet. Restart server.py.')
    a = _lies(_pfad(id_), {})
    gast = '\n'.join(f"{'Customer' if v.get('rolle') == 'user' else 'txtme chat'}: {v.get('text', '')}" for v in a.get('verlauf') or [])
    mail = (f"Kind: {ARTEN.get(a.get('art'), a.get('art'))}\nName: {a.get('name')}\nContact: {a.get('kontakt')}\nPage: {a.get('seite') or 'not stated'}\n"
            f"Language of the customer: {a.get('sprache')}\n\nMESSAGE:\n{a.get('anliegen')}" + (f"\n\nCHAT CONVERSATION:\n{gast}" if gast else ''))
    if gedaechtnis:
        _G.ANFRAGE = _G.ANFRAGE.split('\nKNOWLEDGE:\n')[0] + '\nKNOWLEDGE:\n' + gedaechtnis.wissen_text(_G.WISSEN) + wissen_block()   # the same state as in the chat
    r = _G.anfrage(mail, hinweis, {'art': a.get('art'), 'name': a.get('name'), 'sprache': a.get('sprache')})
    if r.get('fehler'):
        raise ValueError('ENTWURF · ' + r['fehler'])
    with SCHLOSS:
        # read fresh: while the assistant wrote, the team may have changed the request (status, subject); the old state must not overwrite it (17.10.2026)
        a = _lies(_pfad(id_), a)
        a['entwurf'] = {'betreff': r.get('betreff', ''), 'text': r.get('text', ''), 'team': r.get('team', ''), 'absender': ABSENDER.get(a.get('art'), HAUS.get('support', '')),
                        'zeit': _jetzt().isoformat(timespec='seconds'), 'demo': bool(r.get('demo'))}
        a['fassung'] = int(a.get('fassung') or 0) + 1   # a rewritten letter counts the version on (E26)
        if a.get('status') == 'neu':
            a['status'] = 'gelesen'
        _schreib(_pfad(id_), a)
    return {**a['entwurf'], 'fassung': a['fassung']}


# ---------------------------------------------------------------- Browser errors, state, export (R03, E19, E20)
F_FEHLER = None

def fehler_merken(text):
    """Append under the lock (F34), file at most 1 MB."""
    with SCHLOSS:
        os.makedirs(DATEN, exist_ok=True)
        p = _pfad('fehler.jsonl')
        try:
            if os.path.exists(p) and os.path.getsize(p) > 1_000_000:
                os.replace(p, p + '.alt')
        except OSError:
            pass
        with open(p, 'a', encoding='utf-8') as f:
            f.write(json.dumps({'zeit': _jetzt().isoformat(timespec='seconds'), 'text': str(text)[:600]}, ensure_ascii=False) + '\n')

def fehler_liste():
    try:
        zeilen = open(_pfad('fehler.jsonl'), encoding='utf-8').read().splitlines()
    except OSError:
        return []
    aus = []
    for z in zeilen[-200:]:
        try:
            aus.append(json.loads(z))
        except ValueError:
            pass
    return list(reversed(aus))

