                       'stand': datetime.datetime.fromtimestamp(os.path.getmtime(os.path.join(HIER, 'gast_wissen.txt'))).isoformat(timespec='minutes') if os.path.exists(os.path.join(HIER, 'gast_wissen.txt')) else ''},
            'online': {'an': anschluss.an(), 'basis': (HAUS.get('online') or {}).get('basis', '')}, 'anmeldung': 'none until delivery (Master R22)',
            'grenzen': {'anfrage_mb': 3, 'einlesen_mb': 25, 'lesen_min': 600, 'schreiben_min': 60}, 'fehler': len(fehler_liste())}

def export_zip():
    """All data as one ZIP: requests with letters, questions (twelve months), additions and knowledge of the team, without backups (E19)."""
    puffer = io.BytesIO()
    with zipfile.ZipFile(puffer, 'w', zipfile.ZIP_DEFLATED) as z:
        for wurzel, ordner, dateien in os.walk(DATEN):
            ordner[:] = [o for o in ordner if o != 'sicherung']   # without backups (E19, Abnahme 06.11.2026 Fund 6g)
            for f in dateien:
                if f.endswith(('.gut', '.neu', '.alt', '.zip')) or f.startswith('.'):
                    continue
                p = os.path.join(wurzel, f)
                z.write(p, os.path.relpath(p, DATEN))
    return puffer.getvalue()


