        return {**gedaechtnis.get(was, q), 'nachgetragen': nachgetragen()} if was == 'wissen' else gedaechtnis.get(was, q)
    beispiele(); beispiel_fragen()
    if was == 'ueberblick':
        return ueberblick()
    if was == 'anfragen':
        return {'anfragen': _alle('anfragen'), **ueberblick()}
    if was == 'fragen':
        erledigt = set(_lies(_pfad('status.json'), {}).get('fragen_erledigt', []))
        fr = _alle('fragen')
        for f in fr:
            f['erledigt'] = f['id'] in erledigt or (f.get('online_id') in erledigt)
            f['gruppe'] = thema_von(f.get('frage'))
        return {'fragen': fr, 'nachgetragen': nachgetragen(), **ueberblick()}
    if was == 'fehler':
        return {'fehler': fehler_liste()}
    if was == 'zustand':
        return zustand()
    raise ValueError('ANFRAGE · Unknown view.')

def post(was, d):
    if was.startswith('wissen') and gedaechtnis:
        return gedaechtnis.post(was, d)
    if was == 'fehler':             # browser error from the error reporter (R03)
        fehler_merken(d.get('text') or '')
        return {'ok': True}
    beispiele(); beispiel_fragen()
    if was == 'uebersetzen':
        return {**uebersetzen(d.get('id')), **ueberblick()}
    if was == 'entwurf':
        return {'entwurf': entwurf(d.get('id'), feld(d, 'hinweis', 2000, 'The note')), **ueberblick()}
    if was == 'anfrage':            # status or changed letter of the team
        id_ = d.get('id')
        if not _gueltig(id_, 'anfragen'):
            raise ValueError('ANFRAGE · This request no longer exists.')
        if isinstance(d.get('entwurf_text'), str) and len(d['entwurf_text']) > 12000:
            raise ValueError(f"LAENGE · The letter has {len(d['entwurf_text']):,} characters, at most 12,000 fit. Nothing was saved: shorten it and try again.")
        if isinstance(d.get('betreff'), str) and len(d['betreff']) > 300:
            raise ValueError(f"LAENGE · The subject has {len(d['betreff']):,} characters, at most 300 fit. Nothing was saved: shorten it and try again.")
        with SCHLOSS:
            a = _lies(_pfad(id_), {})
            aendert = isinstance(d.get('entwurf_text'), str) or isinstance(d.get('gestalt'), dict)
            if aendert and d.get('fassung') is not None and int(d.get('fassung') or 0) != int(a.get('fassung') or 0):
                raise ValueError('KONFLIKT · Another window saved this letter first. Nothing was overwritten; reload to see the newer version.')
            if d.get('status') in ('neu', 'gelesen', 'erledigt'):
                a['status'] = d['status']
                anschluss.zurueckmelden('eingang', a.get('online_id'), d['status'] == 'erledigt')
            if isinstance(d.get('entwurf_text'), str) and a.get('entwurf'):
                a['entwurf']['text'] = d['entwurf_text'][:12000]
                if isinstance(d.get('betreff'), str):
                    a['entwurf']['betreff'] = d['betreff'][:300]
                a['entwurf']['geaendert'] = _jetzt().isoformat(timespec='seconds')
            if isinstance(d.get('gestalt'), dict) and a.get('entwurf') and len(json.dumps(d['gestalt'])) < 20000:   # arrangement of the letter
                a['entwurf']['gestalt'] = d['gestalt']
            if aendert:
                a['fassung'] = int(a.get('fassung') or 0) + 1
            _schreib(_pfad(id_), a)
        return {'ok': True, 'fassung': a.get('fassung', 0), **ueberblick()}
    if was == 'formular':           # request from a form of the website (same shape as backstage-online/api/eingang.js)
        if d.get('website'):        # field people do not see: only machines fill it in
            return {'ok': True}
        name, kontakt = str(d.get('name') or '').strip()[:120], str(d.get('email') or d.get('kontakt') or '').strip()[:160]
        if d.get('art') not in ARTEN:   # like backstage-online/api/eingang.js: an unknown kind is refused (Abnahme 06.11.2026 Fund 6f)
            raise ValueError('FORMULAR · Unknown kind of request.')
        if not re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+', kontakt):
            raise ValueError('FORMULAR · Please give an e-mail address.')   # the name is optional, as on the website (waiting list, newsletter)
        art = d['art']
        if art not in ('warteliste', 'newsletter') and len(str(d.get('text') or d.get('anliegen') or '').strip()) < 2:
            raise ValueError('FORMULAR · Please write a message.')   # a request without a message is no request; sign-ups need only the address
        sp = d.get('sprache') if d.get('sprache') in SPRACHEN else (d.get('l') if d.get('l') in SPRACHEN else 'en')
        anliegen = str(d.get('text') or d.get('anliegen') or '').strip()[:2000]
        lege_anfrage({'art': art, 'name': name, 'kontakt': kontakt, 'anliegen': anliegen, 'seite': str(d.get('source') or d.get('seite') or '')[:60], 'consent': bool(d.get('consent'))},
                     'formular-' + hashlib.sha1(f'{time.time()}{random.random()}'.encode()).hexdigest()[:12], sp,
                     [{'rolle': 'user', 'text': 'Through the form of the website: ' + anliegen}])
        return {'ok': True}
    if was == 'weg':                # delete a request or question (wish of the customer, test)
        id_ = d.get('id', '')
        art = id_.split('/')[0]
        if art not in ('anfragen', 'fragen') or not _gueltig(id_, art):
            raise ValueError('ANFRAGE · This entry does not exist.')
        with SCHLOSS:
            os.remove(_pfad(id_))
            for rest in (_pfad(id_) + '.gut',):
                try:
                    os.remove(rest)
                except OSError:
                    pass
        return {'ok': True, **ueberblick()}
    if was == 'frage':              # question done / open again
        id_ = d.get('id')
        if not _gueltig(id_, 'fragen'):
            raise ValueError('FRAGE · This question no longer exists.')
        with SCHLOSS:
            f = _lies(_pfad(id_), {})
            s = _lies(_pfad('status.json'), {}); l = [x for x in s.get('fragen_erledigt', []) if x != id_ and x != f.get('online_id')]
            if d.get('erledigt'):
                l.append(id_)
            s['fragen_erledigt'] = l[-5000:]
            _schreib(_pfad('status.json'), s)
        anschluss.zurueckmelden('fragen', f.get('online_id'), bool(d.get('erledigt')))
        return {'ok': True, **ueberblick()}
    if was == 'nachtragen':         # answer of the team to a question without answer
        frage_ = feld(d, 'frage', 400, 'The question'); antwort = feld(d, 'antwort', 2000, 'The answer')
        if len(frage_) < 3 or len(antwort) < 3:
            raise ValueError('EINGABE · Please fill in question and answer.')
        with SCHLOSS:
            l = nachgetragen()
            nid = d.get('nid') or ('n' + str(int(time.time() * 1000)))
            alt = next((x for x in l if x.get('nid') == nid), None)
            eintrag = {'nid': nid, 'frage': frage_, 'antwort': antwort, 'zeit': _jetzt().isoformat(timespec='seconds'),
                       'quelle': d.get('quelle') or (alt or {}).get('quelle') or '', 'von': TEAM}
            l = [x for x in l if x.get('nid') != nid] + [eintrag]
            _schreib(_pfad('nachgetragen.json'), l)
            if d.get('quelle') and _gueltig(d['quelle'], 'fragen'):
                s = _lies(_pfad('status.json'), {}); fe = set(s.get('fragen_erledigt', [])); fe.add(d['quelle'])
                s['fragen_erledigt'] = sorted(fe)[-5000:]; _schreib(_pfad('status.json'), s)
        if gedaechtnis:
            gedaechtnis._merke('nachgetragen', frage_, 'Questions & answers', nid, TEAM)
        return {'ok': True, 'eintrag': eintrag, **ueberblick()}
    if was == 'nachtragen_weg':
        with SCHLOSS:
            _schreib(_pfad('nachgetragen.json'), [x for x in nachgetragen() if x.get('nid') != d.get('nid')])
        return {'ok': True, **ueberblick()}
    if was == 'reparatur':          # check page, confirmed with a second click there
        w = d.get('was')
        if w == 'fehler_leeren':
            with SCHLOSS:
                p = _pfad('fehler.jsonl')
                if os.path.exists(p):
                    os.replace(p, p + '.alt')
            return {'ok': True}
        if w == 'beispiele_neu':    # examples again (only if nothing real lies there)
            if any(not a.get('beispiel') for a in _alle('anfragen')) or any(not f.get('beispiel') for f in _alle('fragen')):
                raise ValueError('REPARATUR · Real entries lie in the inbox; the examples are not re-created.')
            with SCHLOSS:
                for art in ('anfragen', 'fragen'):
                    shutil.rmtree(_pfad(art), ignore_errors=True)
                for n in ('beispiele.json', 'beispiele_fragen.json', 'status.json'):
                    for p in (_pfad(n), _pfad(n) + '.gut'):
                        try:
                            os.remove(p)
                        except OSError:
                            pass
                _schreib(_pfad('nachgetragen.json'), [x for x in nachgetragen() if not x.get('beispiel')])
            beispiele(); beispiel_fragen()
            return {'ok': True, **ueberblick()}
        if w == 'sicherung':        # a ZIP of everything into daten/sicherung/
            os.makedirs(_pfad('sicherung'), exist_ok=True)
            name = 'chat-team-' + _jetzt().strftime('%Y%m%d-%H%M%S') + '.zip'
            open(_pfad('sicherung', name), 'wb').write(export_zip())
            return {'ok': True, 'datei': 'daten/sicherung/' + name}
        raise ValueError('REPARATUR · Unknown repair.')
    raise ValueError('ANFRAGE · Unknown request.')

